import {projectedCar} from './vehicles.js?v=20261018-18';
// Shared projected solid geometry for the process and treatment illustrations.
export const project=(x,y,u=0)=>({x:x+200*u,y:y-68*u});
export const roadPoint=(u,v)=>project(310+158*v,274,u);
export const roadCorners=[[0,0],[1,0],[1,1],[0,1]].map(([u,v])=>{const p=roadPoint(u,v);return [p.x,p.y];});
export const slopePoint=(u,v)=>project(468+182*v,274+150*v,u);
const ridge=[[0,100],[30,111],[100,138],[174,171],[242,216],[275,241],[302,267],[310,274]];
const pair=p=>`${p.x},${p.y}`,path=points=>'M'+points.map(p=>Array.isArray(p)?p.join(','):pair(p)).join('L')+'Z';
const soil=[[310,274],[468,274],[650,424],[332,424]];
const surfaces=[...ridge.slice(0,-1).map((p,i)=>[p,ridge[i+1],[ridge[i+1][0]+200,ridge[i+1][1]-68],[p[0]+200,p[1]-68]]),roadCorners,[[468,274],[668,206],[850,356],[650,424]]];
export function groundHeight(x){let top=424;for(const poly of surfaces)for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length];if(x>=Math.min(a[0],b[0])&&x<=Math.max(a[0],b[0])&&a[0]!==b[0]){const y=a[1]+(x-a[0])/(b[0]-a[0])*(b[1]-a[1]);top=Math.min(top,y);}}return top;}
export function pondPath(wet){const x=302-wet*11,y=269-wet*5;return `M${x},${y}L${x+200},${y-68}L511,206L311,274Q301,282 ${x},${y}Z`;}
export function renderLandscape(prefix='cause',{weather=true,vehicles=true}={}){
 const id=name=>prefix+'-'+name,road=path(roadCorners),front=path(soil),hillFront=path([...ridge,[332,424],[0,424]]);
 const roadLine=(v,cls)=>{const a=roadPoint(0,v),b=roadPoint(1,v);return `<path class="${cls}" d="M${pair(a)}L${pair(b)}"/>`;};
 const top=ridge.slice(0,-1).map((a,i)=>{const b=ridge[i+1];return `<path d="${path([a,b,project(...b,1),project(...a,1)])}" fill="${['#7c947b','#8ba180','#8ca184','#849e80','#8ea789','#98af91','#a9bca0'][i]}" stroke="#a4b89b" stroke-width=".6"/>`;}).join('');
 const trees=[.15,.5,.82].flatMap(u=>[30,78,140].map((x,i)=>{const y=100+x*.4,p=project(x,y,u);return `<g transform="translate(${pair(p)})"><path d="M0,-17V0" stroke="#71816a" stroke-width="2"/><path d="M-6,-8L0,-25L7,-8Z" fill="${i%2?'#536f5a':'#627e60'}"/></g>`;})).join('');
 const contours=[.24,.48,.72].map(t=>{const a=project(468+182*t,274+150*t),b=project(468+182*t,274+150*t,1);return `<path d="M${pair(a)}L${pair(b)}" fill="none" stroke="#9eae8e" stroke-width=".9" opacity=".7"/>`;}).join('');
 const rain=weather?Array.from({length:44},(_,i)=>{const x=18+(i*97)%842,y=groundHeight(x);return `<g class="cause-rain-particle" data-rain-x="${x}" data-rain-ground="${y}"><path class="cause-raindrop" d="M0,0l-2.6,9"/><ellipse class="cause-splash" cx="${x}" cy="${y-1}" rx="3" ry="1.1"/></g>`;}).join(''):'';
 const cars=vehicles?Array.from({length:16},(_,i)=>`<g class="cause-car ${i>3?'extra-car':''}" data-lane="${i%4}" data-car="${i}" style="opacity:0">${projectedCar(i)}</g>`).join(''):'';
 const flowPaths=[.2,.5,.8].map(u=>{const ps=[[100,140],[174,173],[242,218],[275,243],[302,269],[307,275]].map(p=>project(...p,u));return `<path data-runoff-route d="M${ps.map(pair).join('L')}"/>`;}).join('');
 const beads=weather?Array.from({length:18},(_,i)=>`<circle class="cause-runoff-particle" r="2" fill="#9cd9da" data-flow="${i%3}" data-offset="${i/18}"/>`).join(''):'';
 const seep=weather?Array.from({length:12},(_,i)=>`<circle class="cause-seep-particle" r="1.9" fill="#81c4cc" data-flow="${i%2}" data-offset="${i/12}"/>`).join(''):'';
 return `<svg viewBox="0 0 880 500" class="cause-scene solid-landscape" role="img" aria-label="山体与填方的立体剖切示意。双向四车道沿路面纵向延伸，降雨形成地表径流与下渗。"><defs><linearGradient id="${id('sky')}" x2="0" y2="1"><stop stop-color="#e0eae5"/><stop offset="1" stop-color="#f1f3e9"/></linearGradient><linearGradient id="${id('fill')}" x2=".8" y2="1"><stop stop-color="#ddc49e"/><stop offset="1" stop-color="#b6a17c"/></linearGradient><linearGradient id="${id('rock')}" x2=".2" y2="1"><stop stop-color="#b8b6a0"/><stop offset="1" stop-color="#929b84"/></linearGradient><linearGradient id="${id('wet')}" x2="1" y2=".7"><stop stop-color="#6ca2a8" stop-opacity=".7"/><stop offset="1" stop-color="#69949a" stop-opacity=".18"/></linearGradient><pattern id="${id('grain')}" width="17" height="13" patternUnits="userSpaceOnUse"><path d="M2,4l3,1m9,5l2,-1" stroke="#6d6a54" opacity=".22" stroke-width=".8"/></pattern><clipPath id="${id('soil-clip')}"><path d="${front}"/></clipPath><clipPath id="${id('road-clip')}"><path d="${road}"/></clipPath><clipPath id="${id('wetting-front')}"><ellipse cx="324" cy="284" rx="160" ry="80"/></clipPath><marker id="${id('arrow')}" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0L6,3L0,6Z" fill="context-stroke"/></marker></defs>
 <rect width="880" height="500" fill="url(#${id('sky')})"/><path d="M20,437L649,456L865,375L233,355Z" fill="#bcc9b5" opacity=".35"/>
 <path d="${path([[0,424],[332,424],[532,356],[200,356]])}" fill="#8e9c85"/><path class="landscape-hill-face" d="${hillFront}" fill="url(#${id('rock')})"/><path d="${hillFront}" fill="url(#${id('grain')})"/>
 <g class="landscape-terrain-top">${top}${trees}</g><path d="M0,270L332,370M0,330L332,402" stroke="#7e8e76" opacity=".25" fill="none"/>
 <path class="landscape-slope" d="${path([[468,274],[668,206],[850,356],[650,424]])}" fill="#a5b397" stroke="#8ca080" stroke-width="1"/>${contours}
 <g class="landscape-fill-face"><path d="${front}" fill="url(#${id('fill')})"/><path d="${front}" fill="url(#${id('grain')})"/><g clip-path="url(#${id('soil-clip')})" fill="none" stroke="#9d8c6e" opacity=".35"><path d="M305,315Q430,310,550,320M310,363Q460,350,610,368M325,405Q460,393,650,408"/></g></g>
 ${weather?`<path class="cause-wet-zone" clip-path="url(#${id('wetting-front')})" d="${front}" fill="url(#${id('wet')})"/><path class="cause-interface" d="M310,274L330,308L650,424" fill="none" stroke="#bd8d68" stroke-width="2" stroke-dasharray="6,5"/>`:''}
 <path class="cause-road-shadow" d="M310,277L510,209L668,209L468,280Z" fill="#344f46" opacity=".28"/><path d="M310,274L468,274L468,281L310,281Z" fill="#667266"/><path id="${id('road-surface')}" d="${road}" fill="#54675e"/>${roadLine(.25,'cause-lane-dash')}${roadLine(.75,'cause-lane-dash')}${roadLine(.485,'cause-road-median')}${roadLine(.515,'cause-road-median')}${roadLine(.02,'cause-road-edge')}${roadLine(.98,'cause-road-edge')}<g class="cause-vehicles">${cars}</g>
 ${weather?`<path class="cause-pond" id="${id('pond-water')}" d="${pondPath(.3)}" fill="#6ba5ad" opacity=".82"/><path class="cause-pond-ripple" d="M304,270L495,205" stroke="#b8dfdd" fill="none" stroke-width="1.2"/><g class="cause-runoff" fill="none" stroke="#78aeb0" stroke-width="1.8">${flowPaths}</g><g class="cause-runoff-beads">${beads}</g><g class="cause-infiltration" fill="none" stroke="#57929a" stroke-dasharray="3,4" stroke-width="1.5"><path d="M155,220L160,247M230,261L235,287M304,283L316,307" marker-end="url(#${id('arrow')})"/></g><g class="cause-seepage" clip-path="url(#${id('soil-clip')})" fill="none" stroke="#56979f" stroke-width="2.5" stroke-dasharray="7,8"><path data-seep-route d="M302,277Q352,307,426,337T617,411" marker-end="url(#${id('arrow')})"/><path data-seep-route d="M307,296Q354,333,430,359T578,420" marker-end="url(#${id('arrow')})"/></g><g class="cause-seep-beads" clip-path="url(#${id('soil-clip')})">${seep}</g><g class="cause-load-arrows" stroke="#ab8751" stroke-width="2.5" fill="none"><path d="M382,202V238M442,181V217M502,160V196" marker-end="url(#${id('arrow')})"/></g><g class="cause-force-arrows" fill="none" stroke-width="3.5"><path d="M467,343L414,324" stroke="#418875" marker-end="url(#${id('arrow')})"/><path d="M482,354L565,384" stroke="#b66f52" marker-end="url(#${id('arrow')})"/></g><g class="cause-scene-labels"><text x="113" y="298">原有山体</text><text x="387" y="302">填方路基 · 剖切面</text><text x="520" y="440">填方坡面</text><text x="275" y="328" class="cause-water-label">入渗</text><text x="384" y="402" class="cause-water-label">土内渗流</text><text x="537" y="145" class="cause-traffic-label">双向四车道</text></g><g class="cause-cloud" fill="#c7d7cd" opacity=".7"><path d="M54,61q0,-19,21,-20q18,-26,45,-8q23,-5,35,15q21,0,23,13Z"/><path d="M381,48q0,-18,20,-19q15,-19,36,-7q21,-4,33,15q22,-1,26,11Z"/></g><g class="cause-rain" fill="none" stroke="#91b3bd" stroke-width="1.6" stroke-linecap="round">${rain}</g>`:''}
 <text x="23" y="477" class="cause-scene-note">立体构造与过程示意 · 几何不按比例</text></svg>`;
}
